private VerifyResult parseVerifyResponse(String body, String requestedSubjectId) {
    JsonNode root;
    try { root = objectMapper.readTree(body); } catch (Exception e) { throw malformed("unparseable JSON"); }
    JsonNode matchedNode = root.get("matched");
    if (matchedNode == null || !matchedNode.isBoolean()) throw malformed("missing/non-boolean 'matched'");
    JsonNode similarityNode = root.get("similarity");
    if (similarityNode == null || !similarityNode.isNumber() || !Double.isFinite(similarityNode.doubleValue()))
        throw malformed("missing/non-finite 'similarity'");
    JsonNode thresholdNode = root.get("threshold");
    if (thresholdNode == null || !thresholdNode.isNumber() || !Double.isFinite(thresholdNode.doubleValue()))
        throw malformed("missing/non-finite 'threshold'");
    JsonNode livenessNode = root.get("liveness");
    if (livenessNode == null || !livenessNode.isObject()) throw malformed("missing 'liveness' block");
    JsonNode supportedNode = livenessNode.get("supported");
    if (supportedNode == null || !supportedNode.isBoolean()) throw malformed("unreadable liveness.supported");
    JsonNode subjectNode = root.get("subject_id");
    if (subjectNode != null && !subjectNode.isNull()) {
        if (!subjectNode.isTextual() || !requestedSubjectId.equals(subjectNode.textValue()))
            throw malformed("'subject_id' echo mismatch");
    }
    return new VerifyResult(matchedNode.booleanValue(), similarityNode.doubleValue(),
            thresholdNode.doubleValue(), supportedNode.booleanValue(),
            root.path("request_id").asText(null));
}
