    String requestId = root.path("request_id").asText(null);
    JsonNode matched = root.get("matched");
    if (matched == null || !matched.isBoolean()) throw malformedVerify("'matched' must be a JSON boolean", requestId);
    double similarity = requireFiniteNumber(root, "similarity", requestId);
    double threshold = requireFiniteNumber(root, "threshold", requestId);
    JsonNode liveness = root.get("liveness");
    if (liveness == null || !liveness.isObject()) throw malformedVerify("'liveness' block must be an object", requestId);
    JsonNode supported = liveness.get("supported");
    if (supported == null || !supported.isBoolean()) throw malformedVerify("'liveness.supported' must be a JSON boolean", requestId);
    JsonNode subject = root.get("subject_id");
    if (subject != null && !subject.isNull()) {
        if (!subject.isTextual() || requestedSubjectId == null || !requestedSubjectId.equals(subject.textValue())) {
            throw malformedVerify("'subject_id' echo does not match the requested subject", requestId);
        }
    }
    return new VerifyResult(matched.booleanValue(), similarity, threshold, requestId);
}

private double requireFiniteNumber(JsonNode root, String field, String requestId) {
    JsonNode node = root.get(field);
    if (node == null || !node.isNumber() || !Double.isFinite(node.doubleValue())) {
        throw malformedVerify("'" + field + "' must be a finite number", requestId);
    }
    return node.doubleValue();
}

private FaceServiceException malformedVerify(String detail, String requestId) {
    log.warn("face service verify contract violation detail={} requestId={}", detail, requestId == null ? "<none>" : requestId);
    return new FaceServiceException(new FaceServiceError(
        "MALFORMED_RESPONSE", "malformed verify response: " + detail, false, requestId, 200));
}
