private VerifyResult parseVerifyResponse(String body, String requestedSubjectId) {
    JsonNode root;
    try {
        root = objectMapper.readTree(body);
    } catch (Exception unparseable) {
        throw malformedVerify("response is not valid JSON", null);
    }
