package cn.yuanxin.mvp.web.face;

import cn.yuanxin.mvp.web.care.CareFaceVerifier;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.UUID;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * {@link InsightFaceCareVerifier} 活体失败映射测试（IMPORTANT 契约冻结）：
 * {@code LIVENESS_NOT_PASSED}（声明支持活体但本次样本未通过/未返回结果）必须映射为
 * 安全结果 {@link CareFaceVerifier.Outcome#CAPABILITY_UNAVAILABLE}，<b>绝不</b> MATCHED。
 */
class InsightFaceCareVerifierLivenessMappingTest {

    private static final byte[] SYNTHETIC_FACE = "fake-face-bytes".getBytes(StandardCharsets.UTF_8);
    private static final UUID MEMBER_ID = UUID.fromString("00000000-0000-0000-0000-0000000000bb");

    private FaceServiceStub stub;
    private InsightFaceCareVerifier verifier;

    @BeforeEach
    @SuppressWarnings("unchecked")
    void setUp() throws IOException {
        stub = new FaceServiceStub();
        stub.start();
        JdbcTemplate jdbc = mock(JdbcTemplate.class);
        when(jdbc.query(anyString(), any(RowMapper.class), any()))
                .thenReturn(List.of(new InsightFaceCareVerifier.MemberRef("openvela-mvp", "subj-1")));
        InsightFaceProperties props = new InsightFaceProperties(stub.baseUrl(), "openvela-mvp",
                "FAKE-INTERNAL-TOKEN-DO-NOT-USE", null, 1500, 1500, 0.4);
        verifier = new InsightFaceCareVerifier(new FaceServiceClient(props, new ObjectMapper()),
                jdbc, props.verifyThreshold());
    }

    @AfterEach
    void tearDown() {
        stub.close();
    }

    @Test
    @DisplayName("LIVENESS_NOT_PASSED ⇒ CAPABILITY_UNAVAILABLE（绝不 MATCHED）")
    void livenessNotPassedIsCapabilityUnavailable() {
        stub.verify(501, FaceServiceStub.errorBody("LIVENESS_NOT_PASSED", false, "r-lp"));
        CareFaceVerifier.Outcome outcome = verifier.verifyOneToOne("admission", MEMBER_ID, SYNTHETIC_FACE);
        assertThat(outcome).isEqualTo(CareFaceVerifier.Outcome.CAPABILITY_UNAVAILABLE);
        assertThat(outcome).isNotEqualTo(CareFaceVerifier.Outcome.MATCHED);
    }

    @Test
    @DisplayName("LIVENESS_UNSUPPORTED ⇒ CAPABILITY_UNAVAILABLE（既有行为不回归）")
    void livenessUnsupportedStaysCapabilityUnavailable() {
        stub.verify(501, FaceServiceStub.errorBody("LIVENESS_UNSUPPORTED", false, "r-lu"));
        assertThat(verifier.verifyOneToOne("admission", MEMBER_ID, SYNTHETIC_FACE))
                .isEqualTo(CareFaceVerifier.Outcome.CAPABILITY_UNAVAILABLE);
    }
}

package cn.yuanxin.mvp.web.storage;

import cn.yuanxin.mvp.web.media.StoragePort;
import org.yaml.snakeyaml.Yaml;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintStream;
import java.io.Reader;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HexFormat;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * B 真实 OSS 跨语言 smoke 的 Java 侧<b>纯逻辑 harness</b>（root-only、默认绝不执行）。
 *
 * <p>逐字实现 {@code .coordination/B-work/oss-live-smoke/contract.md}：对象键校验（§1）、
 * {@link #smokeBytes}（§2）、阶段执行（§3）、输出行格式化与净化（§4）、三重 opt-in（§5）、
 * UTF-8 YAML 配置读取（§6）。不持有 Spring 上下文；网络/真实 OSS 只发生在 live 模式且由
 * {@link OssLiveSmokeRunner} 注入。</p>
 *
 * <p><b>红线</b>：绝不 list/清空桶；delete 只删单个精确键；绝不输出 bucket/endpoint/region/
 * 完整 key/AK/SK/STS/对象内容；错误消息先经 {@link Redactor} 净化。</p>
 */
public final class OssLiveSmoke {

    public static final String SIDE = "java";
    public static final String PURPOSE = "assessment_result";
    public static final String CONTENT_TYPE = "application/octet-stream";
    public static final int DEFAULT_CONTENT_BYTES = 256;

    static final Pattern OBJECT_KEY_PATTERN = Pattern.compile(
            "^[a-z0-9][a-z0-9._-]{0,31}/assessment_result/"
                    + "[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$");

    static final List<String> PHASES = List.of("write", "verify", "delete", "confirm-absent", "public-url-probe");
    static final List<String> MODES = List.of("live", "double");

    private OssLiveSmoke() {
    }

    // ---------------------------------------------------------------- §2

    /** 契约 §2 的跨语言合成内容算法（两侧逐字一致）。 */
    public static byte[] smokeBytes(String seed, int nbytes) {
        if (seed == null) {
            throw new IllegalArgumentException("content seed must not be null");
        }
        if (nbytes < 0) {
            throw new IllegalArgumentException("content bytes must be >= 0");
        }
        MessageDigest digest;
        try {
            digest = MessageDigest.getInstance("SHA-256");
        } catch (NoSuchAlgorithmException unavailable) {
            throw new IllegalStateException("SHA-256 unavailable", unavailable);
        }
        ByteArrayOutputStream out = new ByteArrayOutputStream(Math.max(32, nbytes));
        int i = 0;
        while (out.size() < nbytes) {
            digest.reset();
            digest.update((seed + ":" + i).getBytes(StandardCharsets.UTF_8));
            out.writeBytes(digest.digest());
            i++;
        }
        byte[] all = out.toByteArray();
        return all.length == nbytes ? all : Arrays.copyOf(all, nbytes);
    }

    public static byte[] sha256(byte[] content) {
        try {
            return MessageDigest.getInstance("SHA-256").digest(content);
        } catch (NoSuchAlgorithmException unavailable) {
            throw new IllegalStateException("SHA-256 unavailable", unavailable);
        }
    }

    public static String sha256Hex(byte[] content) {
        return HexFormat.of().formatHex(sha256(content));
    }

    /** 契约 §4：{@code sha256} 字段取前 12 位十六进制。 */
    public static String sha256Hex12(byte[] content) {
        return sha256Hex(content).substring(0, 12);
    }

    /** 契约 §4：{@code keyDigest = sha256(objectKey UTF-8)} 前 12 位。 */
    public static String keyDigest(String objectKey) {
        return sha256Hex(objectKey.getBytes(StandardCharsets.UTF_8)).substring(0, 12);
    }

    // ---------------------------------------------------------------- §1

    /** 契约 §1 的对象键校验（正则 + 显式负例）。 */
    public static boolean isValidObjectKey(String objectKey) {
        if (objectKey == null || objectKey.isBlank()) {
            return false;
        }
        if (objectKey.contains("..")) {
            return false;
        }
        if (objectKey.startsWith("/") || objectKey.endsWith("/")) {
            return false;
        }
        String[] parts = objectKey.split("/", -1);
        if (parts.length != 3) {
            return false;
        }
        if (!PURPOSE.equals(parts[1])) {
            return false;
        }
        return OBJECT_KEY_PATTERN.matcher(objectKey).matches();
    }

    // ---------------------------------------------------------------- §3 args

    public record Args(String mode, String phase, String objectKey, String contentSeed,
                       int contentBytes, String doubleRoot, String configPath) {
    }

    public static Args parseArgs(String[] argv) {
        String mode = null;
        String phase = null;
        String objectKey = null;
        String seed = null;
        String doubleRoot = null;
        String config = null;
        int contentBytes = DEFAULT_CONTENT_BYTES;
        boolean contentBytesSet = false;
        for (int i = 0; i < argv.length; i++) {
            String flag = argv[i];
            switch (flag) {
                case "--mode" -> mode = requireValue(argv, ++i, flag);
                case "--phase" -> phase = requireValue(argv, ++i, flag);
                case "--object-key" -> objectKey = requireValue(argv, ++i, flag);
                case "--content-seed" -> seed = requireValue(argv, ++i, flag);
                case "--double-root" -> doubleRoot = requireValue(argv, ++i, flag);
                case "--config" -> config = requireValue(argv, ++i, flag);
                case "--content-bytes" -> {
                    String raw = requireValue(argv, ++i, flag);
                    try {
                        contentBytes = Integer.parseInt(raw);
                    } catch (NumberFormatException invalid) {
                        throw new IllegalArgumentException("--content-bytes must be an integer");
                    }
                    contentBytesSet = true;
                }
                default -> throw new IllegalArgumentException("unknown argument: " + flag);
            }
        }
        if (mode == null || !MODES.contains(mode)) {
            throw new IllegalArgumentException("--mode must be one of " + MODES);
        }
        if (phase == null || !PHASES.contains(phase)) {
            throw new IllegalArgumentException("--phase must be one of " + PHASES);
        }
        if (objectKey == null || objectKey.isBlank()) {
            throw new IllegalArgumentException("--object-key is required");
        }
        if (("write".equals(phase) || "verify".equals(phase)) && (seed == null || seed.isBlank())) {
            throw new IllegalArgumentException("--content-seed is required for phase " + phase);
        }
        if (contentBytesSet && contentBytes < 0) {
            throw new IllegalArgumentException("--content-bytes must be >= 0");
        }
        if ("double".equals(mode) && (doubleRoot == null || doubleRoot.isBlank())) {
            throw new IllegalArgumentException("--double-root is required for mode=double");
        }
        if ("live".equals(mode) && (config == null || config.isBlank())) {
            throw new IllegalArgumentException("--config is required for mode=live");
        }
        return new Args(mode, phase, objectKey, seed, contentBytes, doubleRoot, config);
    }

    private static String requireValue(String[] argv, int index, String flag) {
        if (index >= argv.length || argv[index].startsWith("--")) {
            throw new IllegalArgumentException(flag + " requires a value");
        }
        return argv[index];
    }

    // ---------------------------------------------------------------- §6 config

    /** 配置来源：与 {@code AliyunOssProperties} 组件一一对应（值绝不打印）。 */
    public record LiveConfig(String provider, String region, String endpoint, String bucket,
                             String accessKeyId, String accessKeySecret, String securityToken) {
    }

    /** 用 snakeyaml 读 UTF-8 YAML（严禁 ISO-8859-1）。同时兼容嵌套与点号扁平键。 */
    @SuppressWarnings("unchecked")
    public static LiveConfig loadYamlConfig(java.nio.file.Path path) throws IOException {
        try (Reader reader = new InputStreamReader(
                new FileInputStream(path.toFile()), StandardCharsets.UTF_8)) {
            Object loaded = new Yaml().load(reader);
            if (!(loaded instanceof Map<?, ?> root)) {
                throw new IllegalArgumentException("config root is not a YAML mapping");
            }
            Map<String, Object> map = (Map<String, Object>) root;
            return new LiveConfig(
                    value(map, "app.storage.provider"),
                    value(map, "app.storage.oss.region"),
                    value(map, "app.storage.oss.endpoint"),
                    value(map, "app.storage.oss.bucket"),
                    value(map, "app.storage.oss.access-key-id"),
                    value(map, "app.storage.oss.access-key-secret"),
                    value(map, "app.storage.oss.security-token"));
        }
    }

    private static String value(Map<String, Object> root, String dotted) {
        Object flat = root.get(dotted);
        if (flat != null) {
            return String.valueOf(flat).trim();
        }
        Object current = root;
        for (String part : dotted.split("\\.")) {
            if (!(current instanceof Map<?, ?> map)) {
                return null;
            }
            current = map.get(part);
        }
        return current == null ? null : String.valueOf(current).trim();
    }

    // ---------------------------------------------------------------- §5 gate

    public record Gate(boolean pass, String reason, String step, List<String> missingKeys) {
    }

    /** 三重 opt-in；任一不满足即 abort（绝不静默通过）。 */
    public static Gate evaluateGate(String mode, LiveConfig config, boolean liveOptIn) {
        if ("double".equals(mode)) {
            if (liveOptIn) {
                return new Gate(false, "not-opted-in", "double-mode-refuses-live-opt-in", List.of());
            }
            return new Gate(true, "none", "gate", List.of());
        }
        if (config == null || !"aliyun".equals(config.provider())) {
            return new Gate(false, "not-opted-in", "provider-not-aliyun", List.of());
        }
        List<String> missing = new ArrayList<>();
        if (isBlank(config.bucket())) {
            missing.add("app.storage.oss.bucket");
        }
        if (isBlank(config.accessKeyId())) {
            missing.add("app.storage.oss.access-key-id");
        }
        if (isBlank(config.accessKeySecret())) {
            missing.add("app.storage.oss.access-key-secret");
        }
        if (!missing.isEmpty()) {
            return new Gate(false, "missing-config-key", "credentials", List.copyOf(missing));
        }
        if (!liveOptIn) {
            return new Gate(false, "not-opted-in", "missing-live-opt-in", List.of());
        }
        return new Gate(true, "none", "gate", List.of());
    }

    // ---------------------------------------------------------------- §4 output

    /** 阶段结果（不含侧别/模式/键，仅格式化输入）。 */
    public record Execution(String result, String reason, String step, String code,
                            String requestId, int bytes, String sha256) {
    }

    public static Execution ok(String step, int bytes, String sha256) {
        return new Execution("ok", "none", step, "none", "none", bytes, sha256 == null ? "none" : sha256);
    }

    public static Execution fail(String reason, String step, int bytes, String sha256) {
        return new Execution("fail", reason, step, "none", "none", bytes, sha256 == null ? "none" : sha256);
    }

    public static Execution skipped(String reason) {
        return new Execution("skipped", reason, "skipped", "none", "none", -1, "none");
    }

    /** 契约 §4 的唯一定长行。 */
    public static String formatLine(String mode, String phase, Execution execution, String keyDigest,
                                    Redactor redactor) {
        return "[oss-smoke] side=" + SIDE
                + " mode=" + token(redactor.sanitize(mode), "none")
                + " phase=" + token(redactor.sanitize(phase), "none")
                + " step=" + token(redactor.sanitize(execution.step()), "none")
                + " result=" + token(redactor.sanitize(execution.result()), "none")
                + " reason=" + token(redactor.sanitize(execution.reason()), "none")
                + " code=" + token(redactor.sanitize(execution.code()), "none")
                + " requestId=" + token(redactor.sanitize(execution.requestId()), "none")
                + " bytes=" + execution.bytes()
                + " sha256=" + token(redactor.sanitize(execution.sha256()), "none")
                + " keyDigest=" + keyDigest
                + " purpose=" + PURPOSE;
    }

    public static String formatErrorLine(String phase, Throwable failure, Redactor redactor) {
        String exception = failure == null ? "none" : failure.getClass().getSimpleName();
        String message = failure == null ? "none" : failure.getMessage();
        return "[oss-smoke-error] side=" + SIDE
                + " phase=" + token(redactor.sanitize(phase), "none")
                + " exception=" + token(redactor.sanitize(exception), "none")
                + " message=" + token(redactor.sanitize(message), "none");
    }

    private static String token(String value, String emptyValue) {
        if (value == null || value.isBlank()) {
            return emptyValue;
        }
        return value.replaceAll("\\s+", "_");
    }

    /** 敏感值净化器：剔除 bucket/endpoint(+host)/完整 key/AK/SK/STS 及 LTAI 形态子串。 */
    public static final class Redactor {

        private final List<String> literals = new ArrayList<>();
        private final Pattern accessKeyPattern = Pattern.compile("LTAI[A-Za-z0-9]+");

        public static Redactor from(Args args, LiveConfig config) {
            Redactor redactor = new Redactor();
            if (args != null) {
                redactor.add(args.objectKey());
            }
            if (config != null) {
                redactor.add(config.bucket());
                redactor.add(config.endpoint());
                redactor.add(hostOf(config.endpoint()));
                redactor.add(config.accessKeyId());
                redactor.add(config.accessKeySecret());
                redactor.add(config.securityToken());
            }
            return redactor;
        }

        public Redactor add(String value) {
            if (value != null && !value.isBlank()) {
                literals.add(value);
            }
            return this;
        }

        public String sanitize(String message) {
            if (message == null) {
                return "none";
            }
            String out = message;
            for (String literal : literals) {
                out = out.replace(literal, "<redacted>");
            }
            out = accessKeyPattern.matcher(out).replaceAll("<redacted>");
            return out;
        }
    }

    static String hostOf(String endpoint) {
        if (endpoint == null || endpoint.isBlank()) {
            return null;
        }
        String value = endpoint.trim();
        int scheme = value.indexOf("://");
        if (scheme >= 0) {
            value = value.substring(scheme + 3);
        }
        int slash = value.indexOf('/');
        if (slash >= 0) {
            value = value.substring(0, slash);
        }
        return value;
    }

    // ---------------------------------------------------------------- §3 phases

    @FunctionalInterface
    public interface PublicUrlProbe {
        int probe(String endpoint, String bucket, String objectKey) throws Exception;
    }

    /** 阶段执行：只经 {@link StoragePort}；delete 只删传入的单个精确键。 */
    public static Execution executePhase(String mode, String phase, Args args, LiveConfig config,
                                         StoragePort storage, PublicUrlProbe probe) throws Exception {
        String key = args.objectKey();
        switch (phase) {
            case "write" -> {
                byte[] content = smokeBytes(args.contentSeed(), args.contentBytes());
                storage.put(key, new ByteArrayInputStream(content), content.length, CONTENT_TYPE);
                return ok("put", content.length, sha256Hex12(content));
            }
            case "verify" -> {
                if (!storage.exists(key)) {
                    // 验证阶段对象不存在 ⇒ 失败（用"确认不存在"token 如实表达状态）。
                    return fail("absent-confirmed", "exists", -1, "none");
                }
                byte[] actual = storage.get(key);
                if (actual == null) {
                    return fail("adapter-error", "get-null", -1, "none");
                }
                byte[] expected = smokeBytes(args.contentSeed(), args.contentBytes());
                if (actual.length != expected.length) {
                    return fail("bytes-mismatch", "length", actual.length, sha256Hex12(actual));
                }
                if (!Arrays.equals(actual, expected)) {
                    return fail("sha-mismatch", "content", actual.length, sha256Hex12(actual));
                }
                return ok("get", actual.length, sha256Hex12(actual));
            }
            case "delete" -> {
                storage.delete(key);
                return ok("delete", -1, null);
            }
            case "confirm-absent" -> {
                if (storage.exists(key)) {
                    return fail("still-exists", "exists", -1, "none");
                }
                return ok("absent-confirmed", -1, null);
            }
            case "public-url-probe" -> {
                if (!"live".equals(mode)) {
                    return skipped("no-live-bucket");
                }
                int status = probe.probe(config.endpoint(), config.bucket(), key);
                if (status == 200) {
                    return fail("public-url-status-200", "public-url-status-" + status, -1, "none");
                }
                // step 只携带 HTTP 状态码；绝不打印 URL/bucket/key。
                return ok("public-url-status-" + status, -1, null);
            }
            default -> throw new IllegalArgumentException("unsupported phase: " + phase);
        }
    }

    /** 未鉴权公开 URL（仅用于探测；绝不打印其返回值）。 */
    public static URI publicUrl(String endpoint, String bucket, String objectKey) {
        String value = endpoint == null ? "" : endpoint.trim();
        String scheme = "https";
        int schemeIdx = value.indexOf("://");
        if (schemeIdx >= 0) {
            scheme = value.substring(0, schemeIdx).toLowerCase(Locale.ROOT);
            value = value.substring(schemeIdx + 3);
        }
        while (value.endsWith("/")) {
            value = value.substring(0, value.length() - 1);
        }
        return URI.create(scheme + "://" + bucket + "." + value + "/" + objectKey);
    }

    // ---------------------------------------------------------------- run

    /** 由 runner 注入的存储构造（live 构造真实 OSS，double 构造文件替身）。 */
    public interface StorageFactory {
        StorageSession open(String mode, Args args, LiveConfig config) throws Exception;
    }

    public interface StorageSession {
        StoragePort port();

        void close();
    }

    /**
     * 完整编排（可单测）：解析参数 → 键校验 → 三重门 → 打开存储 → 执行阶段 → 输出。
     *
     * @return 进程退出码：成功 0、任何 fail/abort 非 0
     */
    public static int run(String[] argv, PrintStream out, boolean liveOptIn,
                          PublicUrlProbe probe, StorageFactory storageFactory) {
        Args args;
        try {
            args = parseArgs(argv);
        } catch (RuntimeException usageError) {
            out.println(formatErrorLine("none", usageError, new Redactor()));
            return 2;
        }
        Redactor parseRedactor = Redactor.from(args, null);
        if (!isValidObjectKey(args.objectKey())) {
            out.println(formatLine(args.mode(), args.phase(),
                    fail("invalid-object-key", "key-format", -1, "none"),
                    keyDigest(args.objectKey()), parseRedactor));
            return 2;
        }

        LiveConfig config = null;
        if ("live".equals(args.mode())) {
            try {
                config = loadYamlConfig(java.nio.file.Path.of(args.configPath()));
            } catch (Exception configFailure) {
                Redactor redactor = Redactor.from(args, null);
                out.println(formatLine(args.mode(), args.phase(),
                        fail("missing-config-key", "config", -1, "none"),
                        keyDigest(args.objectKey()), redactor));
                out.println(formatErrorLine(args.phase(), configFailure, redactor));
                return 2;
            }
        }

        Redactor redactor = Redactor.from(args, config);
        Gate gate = evaluateGate(args.mode(), config, liveOptIn);
        if (!gate.pass()) {
            out.println(formatLine(args.mode(), args.phase(),
                    fail(gate.reason(), gate.step(), -1, "none"),
                    keyDigest(args.objectKey()), redactor));
            if (!gate.missingKeys().isEmpty()) {
                // 只报缺失键名，绝不报其值。
                out.println(formatErrorLine(args.phase(),
                        new IllegalStateException("missing config keys: "
                                + String.join(", ", gate.missingKeys())), redactor));
            }
            return 2;
        }

        StorageSession session = null;
        try {
            session = storageFactory.open(args.mode(), args, config);
            Execution execution = executePhase(args.mode(), args.phase(), args, config,
                    session.port(), probe);
            out.println(formatLine(args.mode(), args.phase(), execution,
                    keyDigest(args.objectKey()), redactor));
            return "ok".equals(execution.result()) || "skipped".equals(execution.result()) ? 0 : 1;
        } catch (Exception adapterFailure) {
            out.println(formatLine(args.mode(), args.phase(),
                    fail("adapter-error", "exception", -1, "none"),
                    keyDigest(args.objectKey()), redactor));
            out.println(formatErrorLine(args.phase(), adapterFailure, redactor));
            return 1;
        } finally {
            if (session != null) {
                session.close();
            }
        }
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}

package cn.yuanxin.mvp.web.storage;

import cn.yuanxin.mvp.web.config.AppProperties;
import cn.yuanxin.mvp.web.media.StoragePort;
import cn.yuanxin.mvp.web.testdouble.FileSystemStorageDouble;
import com.aliyun.oss.OSS;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;

/**
 * B 真实 OSS 跨语言 smoke 的 Java 侧 CLI 入口（root-only）。由驱动以
 * {@code java -cp target/test-classes:target/classes:<deps> cn.yuanxin.mvp.web.storage.OssLiveSmokeRunner ...}
 * 调用；类名不以 {@code Test}/{@code IT} 结尾 ⇒ surefire 绝不执行它。
 *
 * <p>仅做接线：真实 OSS 只经生产装配 {@link OssProvidersConfig#ossClient} 构造，put/get/exists/delete
 * 全部由 {@link OssStorageAdapter} 执行；{@code --mode double} 用 {@link FileSystemStorageDouble}。
 * 安全与格式逻辑在 {@link OssLiveSmoke}（可单测）。</p>
 */
public final class OssLiveSmokeRunner {

    private OssLiveSmokeRunner() {
    }

    public static void main(String[] rawArgs) {
        boolean liveOptIn = Boolean.getBoolean("app.oss.live-smoke");
        int exitCode = OssLiveSmoke.run(rawArgs, System.out, liveOptIn,
                OssLiveSmokeRunner::httpProbe, OssLiveSmokeRunner::openStorage);
        System.out.flush();
        System.exit(exitCode);
    }

    /** live ⇒ 生产装配 + 生产适配器；double ⇒ 文件系统替身。 */
    static OssLiveSmoke.StorageSession openStorage(String mode, OssLiveSmoke.Args args,
                                                   OssLiveSmoke.LiveConfig config) {
        if ("double".equals(mode)) {
            FileSystemStorageDouble storage = new FileSystemStorageDouble(args.doubleRoot());
            return session(storage, () -> {
            });
        }
        // 与 OssProvidersConfig:59-71 完全一致的参数：endpoint/region/credentials/超时。
        AliyunOssProperties properties = new AliyunOssProperties(
                config.region(), config.endpoint(), config.bucket(),
                config.accessKeyId(), config.accessKeySecret(), config.securityToken(), null, null);
        // 生产装配要求 app.storage.bucket 与 app.storage.oss.bucket 一致。
        AppProperties appProperties = new AppProperties(null, null,
                new AppProperties.Storage(null, config.bucket()), null, null, null, null);
        OSS oss = new OssProvidersConfig().ossClient(properties, appProperties);
        OssStorageAdapter adapter = new OssStorageAdapter(oss, properties.bucket());
        return session(adapter, oss::shutdown);
    }

    private static OssLiveSmoke.StorageSession session(StoragePort port, Runnable close) {
        return new OssLiveSmoke.StorageSession() {
            @Override
            public StoragePort port() {
                return port;
            }

            @Override
            public void close() {
                close.run();
            }
        };
    }

    /** 未鉴权 GET（无 Authorization、不跟随重定向、10s 超时）；只返回状态码，绝不打印 URL。 */
    static int httpProbe(String endpoint, String bucket, String objectKey) throws Exception {
        URI uri = OssLiveSmoke.publicUrl(endpoint, bucket, objectKey);
        HttpClient client = HttpClient.newBuilder()
                .followRedirects(HttpClient.Redirect.NEVER)
                .connectTimeout(Duration.ofSeconds(10))
                .build();
        HttpRequest request = HttpRequest.newBuilder(uri)
                .timeout(Duration.ofSeconds(10))
                .GET()
                .header("Accept", "*/*")
                .build();
        HttpResponse<Void> response = client.send(request, HttpResponse.BodyHandlers.discarding());
        return response.statusCode();
    }
}

package cn.yuanxin.mvp.web.storage;

import cn.yuanxin.mvp.web.media.StoragePort;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * {@link OssLiveSmoke} 本地回归（<b>绝不联网</b>、<b>绝不使用真实凭据</b>）：
 * 权威跨语言向量、键校验、输出净化、三重 opt-in、double 全流程，以及 live 阶段的注入式验证。
 */
class OssLiveSmokeTest {

    private static final String SEED = "b-oss-smoke-vector";
    private static final String VALID_KEY = "dev/assessment_result/00000000-0000-4000-8000-000000000000";
    private static final String BUCKET = "fake-bucket-do-not-use";
    private static final String ENDPOINT = "https://oss-cn-hangzhou.aliyuncs.com";
    private static final String AK = "LTAI-FAKE-DO-NOT-USE";
    private static final String SK = "FAKE-SECRET-DO-NOT-USE";
    private static final String STS = "FAKE-STS-DO-NOT-USE";

    // ------------------------------------------------------------ 1. 权威向量

    @Test
    @DisplayName("smokeBytes 与 Python 侧硬编码权威向量逐字一致（256/64/1）")
    void authoritativeVectorsMatchContract() {
        assertThat(OssLiveSmoke.sha256Hex(OssLiveSmoke.smokeBytes(SEED, 256)))
                .isEqualTo("0e46beb450377892dc132e1f97087b55311f042a8757d105c03a1a2030e14e32");
        assertThat(OssLiveSmoke.sha256Hex(OssLiveSmoke.smokeBytes(SEED, 64)))
                .isEqualTo("f3a9429115790ee322b3f4a20263f2c9e1ad286928c7f9fac6d4a6cd93c258fd");
        assertThat(OssLiveSmoke.sha256Hex(OssLiveSmoke.smokeBytes(SEED, 1)))
                .isEqualTo("0a43b22d89fa2499be5c7704c9bf273260b0ca9588e4cd1897cd80f9c96cd97a");
    }

    @Test
    @DisplayName("keyDigest 与契约示例一致（6ca2e86b3621）")
    void keyDigestMatchesContractExample() {
        assertThat(OssLiveSmoke.keyDigest(VALID_KEY)).isEqualTo("6ca2e86b3621");
    }

    // ------------------------------------------------------------ 2. 键校验

    @Test
    @DisplayName("合法对象键通过")
    void validObjectKeysAccepted() {
        assertThat(OssLiveSmoke.isValidObjectKey(VALID_KEY)).isTrue();
        assertThat(OssLiveSmoke.isValidObjectKey(
                "prod-1/assessment_result/abcdef01-2345-6789-abcd-ef0123456789")).isTrue();
        assertThat(OssLiveSmoke.isValidObjectKey(
                "a.b_c-1/assessment_result/abcdef01-2345-6789-abcd-ef0123456789")).isTrue();
    }

    @Test
    @DisplayName("非法对象键逐一拒绝（.. / 首尾斜杠 / 段数 / purpose / UUID / 大写）")
    void invalidObjectKeysRejected() {
        List<String> invalid = List.of(
                "dev/assessment_result/00000000-0000-4000-8000-00000000000",
                "dev/assessment_result/00000000-0000-4000-8000-0000000000000",
                "../assessment_result/00000000-0000-4000-8000-000000000000",
                "dev/assessment_result/00000000-0000-4000-8000-000000000000/",
                "/dev/assessment_result/00000000-0000-4000-8000-000000000000",
                "dev/grant_face/00000000-0000-4000-8000-000000000000",
                "dev/assessment_result",
                "dev/assessment_result/x/y",
                "DEV/assessment_result/00000000-0000-4000-8000-000000000000",
                "dev/assessment_result/00000000-0000-4000-8000-00000000000G",
                "dev/assessment_result/00000000000000000000000000000000",
                "a..b/assessment_result/00000000-0000-4000-8000-000000000000");
        for (String key : invalid) {
            assertThat(OssLiveSmoke.isValidObjectKey(key)).as("must reject: %s", key).isFalse();
        }
    }

    // ------------------------------------------------------------ 3. 净化

    @Test
    @DisplayName("净化：输出行不含 bucket/完整 key/endpoint/假 AK/SK/STS，且含 keyDigest（live/double 两模式）")
    void sanitizationRemovesSecrets() {
        OssLiveSmoke.LiveConfig config = new OssLiveSmoke.LiveConfig(
                "aliyun", "cn-hangzhou", ENDPOINT, BUCKET, AK, SK, STS);
        OssLiveSmoke.Args args = new OssLiveSmoke.Args("live", "write", VALID_KEY, SEED, 256, null, null);
        OssLiveSmoke.Redactor redactor = OssLiveSmoke.Redactor.from(args, config);

        String dirty = "bucket=" + BUCKET + " endpoint=" + ENDPOINT + " key=" + VALID_KEY
                + " ak=" + AK + " sk=" + SK + " sts=" + STS + " raw=" + "LTAIABCDEFGHIJKLMNOP";
        String cleaned = redactor.sanitize(dirty);
        assertNoSecrets(cleaned);

        String digest = OssLiveSmoke.keyDigest(VALID_KEY);
        for (String mode : List.of("live", "double")) {
            OssLiveSmoke.Execution malicious = new OssLiveSmoke.Execution(
                    "ok", "none", "step-" + VALID_KEY + "-" + BUCKET,
                    "code-" + AK, "req-" + SK, 256, "none");
            String line = OssLiveSmoke.formatLine(mode, "write", malicious, digest, redactor);
            assertThat(line).contains("side=java").contains("mode=" + mode)
                    .contains("keyDigest=" + digest).contains("purpose=assessment_result");
            assertNoSecrets(line);
        }
    }

    // ------------------------------------------------------------ 4. 三重门

    @Test
    @DisplayName("三重门：逐项缺失即 abort（provider / 凭据 / opt-in）")
    void gateRejectsEachMissingCondition() {
        assertThat(OssLiveSmoke.evaluateGate("live",
                new OssLiveSmoke.LiveConfig("doubles", "cn-hangzhou", ENDPOINT, BUCKET, AK, SK, null), true))
                .satisfies(gate -> {
                    assertThat(gate.pass()).isFalse();
                    assertThat(gate.reason()).isEqualTo("not-opted-in");
                    assertThat(gate.step()).isEqualTo("provider-not-aliyun");
                });
        OssLiveSmoke.Gate missingCreds = OssLiveSmoke.evaluateGate("live",
                new OssLiveSmoke.LiveConfig("aliyun", "cn-hangzhou", ENDPOINT, null, AK, null, null), true);
        assertThat(missingCreds.pass()).isFalse();
        assertThat(missingCreds.reason()).isEqualTo("missing-config-key");
        assertThat(missingCreds.missingKeys()).containsExactly(
                "app.storage.oss.bucket", "app.storage.oss.access-key-secret");
        OssLiveSmoke.Gate noOptIn = OssLiveSmoke.evaluateGate("live",
                new OssLiveSmoke.LiveConfig("aliyun", "cn-hangzhou", ENDPOINT, BUCKET, AK, SK, null), false);
        assertThat(noOptIn.pass()).isFalse();
        assertThat(noOptIn.reason()).isEqualTo("not-opted-in");
        assertThat(noOptIn.step()).isEqualTo("missing-live-opt-in");
        assertThat(OssLiveSmoke.evaluateGate("live",
                new OssLiveSmoke.LiveConfig("aliyun", "cn-hangzhou", ENDPOINT, BUCKET, AK, SK, null), true)
                .pass()).isTrue();
    }

    @Test
    @DisplayName("double 模式遇 opt-in=true 必须 abort（not-opted-in / double-mode-refuses-live-opt-in）")
    void doubleModeRefusesLiveOptIn() {
        OssLiveSmoke.Gate gate = OssLiveSmoke.evaluateGate("double", null, true);
        assertThat(gate.pass()).isFalse();
        assertThat(gate.reason()).isEqualTo("not-opted-in");
        assertThat(gate.step()).isEqualTo("double-mode-refuses-live-opt-in");
    }

    // ------------------------------------------------------------ 5. double 全流程

    @Test
    @DisplayName("double 全流程 write→verify→delete→confirm-absent 每步 ok，且磁盘上对象确被删除")
    void doubleFullFlow(@TempDir Path root) throws Exception {
        OssLiveSmoke.StorageFactory factory = doubleFactory();
        String[] writeArgv = argv("double", "write", root, VALID_KEY, 256);
        String writeLine = runLine(writeArgv, false, (e, b, k) -> 0, factory, 0);
        String sha12 = OssLiveSmoke.sha256Hex12(OssLiveSmoke.smokeBytes(SEED, 256)).substring(0, 12);
        assertThat(writeLine).contains("result=ok").contains("bytes=256").contains("sha256=" + sha12);

        String verifyLine = runLine(argv("double", "verify", root, VALID_KEY, 256),
                false, (e, b, k) -> 0, factory, 0);
        assertThat(verifyLine).contains("result=ok").contains("bytes=256").contains("sha256=" + sha12);

        Path onDisk = root.resolve(VALID_KEY).normalize();
        assertThat(Files.isRegularFile(onDisk)).isTrue();

        String deleteLine = runLine(argv("double", "delete", root, VALID_KEY, 256),
                false, (e, b, k) -> 0, factory, 0);
        assertThat(deleteLine).contains("result=ok");
        assertThat(Files.exists(onDisk)).isFalse();

        String confirmLine = runLine(argv("double", "confirm-absent", root, VALID_KEY, 256),
                false, (e, b, k) -> 0, factory, 0);
        assertThat(confirmLine).contains("result=ok").contains("reason=absent-confirmed");
    }

    @Test
    @DisplayName("double 模式 public-url-probe → skipped/no-live-bucket（退出码 0）")
    void doubleProbeSkipped(@TempDir Path root) {
        String line = runLine(argv("double", "public-url-probe", root, VALID_KEY, 256),
                false, (e, b, k) -> 200, doubleFactory(), 0);
        assertThat(line).contains("result=skipped").contains("reason=no-live-bucket");
    }

    // ------------------------------------------------------------ live 注入式

    @Test
    @DisplayName("live 门通过后用注入假存储执行：write/verify 正常；public-url-probe 403→ok、200→fail")
    void livePhaseWithInjectedStorageAndProbe(@TempDir Path tempDir) throws Exception {
        Path config = writeFakeYaml(tempDir);
        MapStorage shared = new MapStorage();
        OssLiveSmoke.StorageFactory factory = (mode, args, cfg) -> session(shared);

        String writeLine = runLine(argvLive(config, "write", VALID_KEY, 256),
                true, (e, b, k) -> 0, factory, 0);
        assertThat(writeLine).contains("mode=live").contains("result=ok");

        String verifyLine = runLine(argvLive(config, "verify", VALID_KEY, 256),
                true, (e, b, k) -> 0, factory, 0);
        assertThat(verifyLine).contains("result=ok");

        String probe403 = runLine(argvLive(config, "public-url-probe", VALID_KEY, 256),
                true, (e, b, k) -> 403, factory, 0);
        assertThat(probe403).contains("result=ok").contains("step=public-url-status-403");
        assertThat(probe403).doesNotContain("http").doesNotContain(BUCKET).doesNotContain(VALID_KEY);

        String probe200 = runLine(argvLive(config, "public-url-probe", VALID_KEY, 256),
                true, (e, b, k) -> 200, factory, 1);
        assertThat(probe200).contains("result=fail").contains("reason=public-url-status-200");
    }

    @Test
    @DisplayName("三重门缺 opt-in 时 live abort，不打开存储（exit 2）")
    void liveGateAbortsWithoutOptIn(@TempDir Path tempDir) throws Exception {
        Path config = writeFakeYaml(tempDir);
        boolean[] opened = {false};
        OssLiveSmoke.StorageFactory factory = (mode, args, cfg) -> {
            opened[0] = true;
            return session(new MapStorage());
        };
        String line = runLine(argvLive(config, "write", VALID_KEY, 256),
                false, (e, b, k) -> 0, factory, 2);
        assertThat(line).contains("result=fail").contains("reason=not-opted-in");
        assertThat(opened[0]).isFalse();
    }

    // ------------------------------------------------------------ 错误净化

    @Test
    @DisplayName("适配器异常：输出 result=fail reason=adapter-error，且异常消息经净化（无 bucket/key/AK/SK/STS）")
    void adapterErrorIsSanitized(@TempDir Path tempDir) throws Exception {
        Path config = writeFakeYaml(tempDir);
        RuntimeException leaky = new RuntimeException("bucket=" + BUCKET + " key=" + VALID_KEY
                + " endpoint=" + ENDPOINT + " ak=" + AK + " sk=" + SK + " sts=" + STS
                + " LTAILEAKEDSECRET");
        OssLiveSmoke.StorageFactory factory = (mode, args, cfg) -> session(new ThrowingStorage(leaky));

        String output = runAll(argvLive(config, "verify", VALID_KEY, 256),
                true, (e, b, k) -> 0, factory, 1);
        assertThat(output).contains("result=fail").contains("reason=adapter-error")
                .contains("[oss-smoke-error]")
                .contains("keyDigest=" + OssLiveSmoke.keyDigest(VALID_KEY));
        assertNoSecrets(output);
    }

    @Test
    @DisplayName("double 模式异常净化：输出不含完整 key，但含 keyDigest")
    void doubleAdapterErrorIsSanitized(@TempDir Path root) {
        OssLiveSmoke.StorageFactory factory = (mode, args, cfg) ->
                session(new ThrowingStorage(new IllegalStateException("key=" + VALID_KEY)));
        String output = runAll(argv("double", "delete", root, VALID_KEY, 256),
                false, (e, b, k) -> 0, factory, 1);
        assertThat(output).contains("result=fail").contains("reason=adapter-error")
                .contains("keyDigest=" + OssLiveSmoke.keyDigest(VALID_KEY));
        assertThat(output).doesNotContain(VALID_KEY);
    }

    // ------------------------------------------------------------ 非法键 / 用法

    @Test
    @DisplayName("非法对象键在阶段前 fail/invalid-object-key（exit 2），不打开存储")
    void invalidKeyRejectedBeforePhases(@TempDir Path root) {
        boolean[] opened = {false};
        OssLiveSmoke.StorageFactory factory = (mode, args, cfg) -> {
            opened[0] = true;
            return session(new MapStorage());
        };
        String[] argv = {"--mode", "double", "--phase", "write",
                "--object-key", "dev/grant_face/00000000-0000-4000-8000-000000000000",
                "--content-seed", SEED, "--double-root", root.toString()};
        String line = runLine(argv, false, (e, b, k) -> 0, factory, 2);
        assertThat(line).contains("result=fail").contains("reason=invalid-object-key");
        assertThat(opened[0]).isFalse();
    }

    @Test
    @DisplayName("配置为 UTF-8 嵌套与点号扁平键均可读取")
    void yamlConfigReadBothShapes(@TempDir Path tempDir) throws Exception {
        Path nested = tempDir.resolve("nested.yml");
        Files.writeString(nested, ""
                + "app:\n"
                + "  storage:\n"
                + "    provider: aliyun\n"
                + "    oss:\n"
                + "      region: cn-hangzhou\n"
                + "      endpoint: " + ENDPOINT + "\n"
                + "      bucket: " + BUCKET + "\n"
                + "      access-key-id: " + AK + "\n"
                + "      access-key-secret: " + SK + "\n"
                + "      security-token: " + STS + "\n", StandardCharsets.UTF_8);
        OssLiveSmoke.LiveConfig nestedConfig = OssLiveSmoke.loadYamlConfig(nested);
        assertThat(nestedConfig.provider()).isEqualTo("aliyun");
        assertThat(nestedConfig.bucket()).isEqualTo(BUCKET);
        assertThat(nestedConfig.accessKeyId()).isEqualTo(AK);
        assertThat(nestedConfig.securityToken()).isEqualTo(STS);

        Path flat = tempDir.resolve("flat.yml");
        Files.writeString(flat, ""
                + "app.storage.provider: aliyun\n"
                + "app.storage.oss.region: cn-hangzhou\n"
                + "app.storage.oss.endpoint: " + ENDPOINT + "\n"
                + "app.storage.oss.bucket: " + BUCKET + "\n"
                + "app.storage.oss.access-key-id: " + AK + "\n"
                + "app.storage.oss.access-key-secret: " + SK + "\n", StandardCharsets.UTF_8);
        OssLiveSmoke.LiveConfig flatConfig = OssLiveSmoke.loadYamlConfig(flat);
        assertThat(flatConfig.provider()).isEqualTo("aliyun");
        assertThat(flatConfig.bucket()).isEqualTo(BUCKET);
    }

    // ------------------------------------------------------------ helpers

    private static void assertNoSecrets(String text) {
        assertThat(text).doesNotContain(BUCKET)
                .doesNotContain(VALID_KEY)
                .doesNotContain(ENDPOINT)
                .doesNotContain(AK)
                .doesNotContain(SK)
                .doesNotContain(STS)
                .doesNotContain("LTAI");
    }

    private static String[] argv(String mode, String phase, Path root, String key, int nbytes) {
        return new String[]{"--mode", mode, "--phase", phase, "--object-key", key,
                "--content-seed", SEED, "--content-bytes", String.valueOf(nbytes),
                "--double-root", root.toString()};
    }

    private static String[] argvLive(Path config, String phase, String key, int nbytes) {
        return new String[]{"--mode", "live", "--phase", phase, "--object-key", key,
                "--content-seed", SEED, "--content-bytes", String.valueOf(nbytes),
                "--config", config.toString()};
    }

    private static Path writeFakeYaml(Path dir) throws Exception {
        Path config = dir.resolve("fake.yml");
        Files.writeString(config, ""
                + "app:\n"
                + "  storage:\n"
                + "    provider: aliyun\n"
                + "    oss:\n"
                + "      region: cn-hangzhou\n"
                + "      endpoint: " + ENDPOINT + "\n"
                + "      bucket: " + BUCKET + "\n"
                + "      access-key-id: " + AK + "\n"
                + "      access-key-secret: " + SK + "\n"
                + "      security-token: " + STS + "\n", StandardCharsets.UTF_8);
        return config;
    }

    private static OssLiveSmoke.StorageFactory doubleFactory() {
        return (mode, args, cfg) ->
                session(new FileSystemStorageDouble(args.doubleRoot()));
    }

    private static OssLiveSmoke.StorageSession session(StoragePort port) {
        return new OssLiveSmoke.StorageSession() {
            @Override
            public StoragePort port() {
                return port;
            }

            @Override
            public void close() {
            }
        };
    }

    private static String runLine(String[] argv, boolean optIn, OssLiveSmoke.PublicUrlProbe probe,
                                  OssLiveSmoke.StorageFactory factory, int expectedExit) {
        String output = runAll(argv, optIn, probe, factory, expectedExit);
        return output.lines().filter(line -> line.startsWith("[oss-smoke]")).findFirst().orElse("");
    }

    private static String runAll(String[] argv, boolean optIn, OssLiveSmoke.PublicUrlProbe probe,
                                 OssLiveSmoke.StorageFactory factory, int expectedExit) {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        int exit;
        try (PrintStream out = new PrintStream(buffer, true, StandardCharsets.UTF_8)) {
            exit = OssLiveSmoke.run(argv, out, optIn, probe, factory);
        }
        assertThat(exit).as("exit code").isEqualTo(expectedExit);
        return buffer.toString(StandardCharsets.UTF_8);
    }

    /** 内存假存储（绝不联网）。 */
    private static final class MapStorage implements StoragePort {
        private final Map<String, byte[]> data = new ConcurrentHashMap<>();

        @Override
        public void put(String objectKey, InputStream content, long byteSize, String contentType) {
            try {
                data.put(objectKey, content.readAllBytes());
            } catch (Exception failure) {
                throw new IllegalStateException("put failed", failure);
            }
        }

        @Override
        public InputStream getStream(String objectKey) {
            byte[] value = data.get(objectKey);
            return value == null ? null : new ByteArrayInputStream(value);
        }

        @Override
        public byte[] get(String objectKey) {
            return data.get(objectKey);
        }

        @Override
        public boolean exists(String objectKey) {
            return data.containsKey(objectKey);
        }

        @Override
        public void delete(String objectKey) {
            data.remove(objectKey);
        }
    }

    /** 始终抛异常的假存储，用于净化测试。 */
    private static final class ThrowingStorage implements StoragePort {
        private final RuntimeException failure;

        private ThrowingStorage(RuntimeException failure) {
            this.failure = failure;
        }

        @Override
        public void put(String objectKey, InputStream content, long byteSize, String contentType) {
            throw failure;
        }

        @Override
        public InputStream getStream(String objectKey) {
            throw failure;
        }

        @Override
        public byte[] get(String objectKey) {
            throw failure;
        }

        @Override
        public boolean exists(String objectKey) {
            throw failure;
        }

        @Override
        public void delete(String objectKey) {
            throw failure;
        }
    }
}

