package cn.yuanxin.mvp.web.state;

import java.io.PrintStream;

/**
 * L3 清理编排的纯函数（包级可见，便于单测）：执行 Redis 删除 → SCAN 复核 → DB 删除，
 * 并保证：只要任一步骤异常（或 SCAN 残留），最终抛出 IllegalStateException（测试必须是 FAIL 而非 PASS），
 * 其余异常以 addSuppressed 保留。输出只含计数与异常类名。
 */
final class L3Cleanup {

    @FunctionalInterface interface RedisDelete { void run(); }
    @FunctionalInterface interface RedisScan { int leftoverKeys(); }
    /** 返回 {destinationsDeleted, accountsDeleted}。 */
    @FunctionalInterface interface DbDelete { int[] run(); }

    private L3Cleanup() {}

    static void run(RedisDelete redisDelete, RedisScan redisScan, DbDelete dbDelete, PrintStream out) {
        Throwable failure = null;
        try { redisDelete.run(); } catch (RuntimeException e) { failure = e; }
        int leftover;
        try { leftover = redisScan.leftoverKeys(); }
        catch (RuntimeException e) { failure = accumulate(failure, e); leftover = -1; }

        int destinationsDeleted = 0;
        int accountsDeleted = 0;
        try {
            int[] counts = dbDelete.run();
            if (counts != null && counts.length >= 2) { destinationsDeleted = counts[0]; accountsDeleted = counts[1]; }
        } catch (RuntimeException e) {
            failure = accumulate(failure, e);
            out.println("[l3-cleanup] db-cleanup-error exception=" + e.getClass().getSimpleName());
        }

        out.println("[l3-cleanup] redisLeftover=" + leftover
                + " destinationsDeleted=" + destinationsDeleted
                + " accountsDeleted=" + accountsDeleted
                + (failure == null ? "" : " cleanup-incomplete-suppressed=" + failure.getClass().getSimpleName()));

        if (failure != null) {
            IllegalStateException incomplete = new IllegalStateException(
                    "cleanup incomplete: leftover keys under test prefix = "
                            + (leftover < 0 ? "unverified" : leftover) + " (names not logged)");
            incomplete.addSuppressed(failure);
            throw incomplete;
        }
    }

    private static Throwable accumulate(Throwable existing, RuntimeException next) {
        if (existing == null) return next;
        existing.addSuppressed(next);
        return existing;
    }
}
```
