package cn.yuanxin.mvp.web.state;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.dao.QueryTimeoutException;
import org.springframework.data.redis.RedisConnectionFailureException;

import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.charset.StandardCharsets;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * {@link L3Cleanup} 判别测试（不需 Spring/Redis）：证明<b>只要任一步骤异常（或 SCAN 残留/无法复核），
 * 清理就必须失败</b>——尤其是"删除抛异常但键其实已不存在（SCAN=0）"这一 IMPORTANT 4 未闭合场景。
 */
class L3CleanupTest {

    @Test
    @DisplayName("Redis 删除抛异常但 SCAN=0 ⇒ 仍必须失败（不能只打印却 PASS）")
    void deleteThrowsButScanZeroStillFails() {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        IllegalStateException thrown = runExpectingFailure(
                () -> {
                    throw new RedisConnectionFailureException(
                            "Unable to connect to redis://user:secret@10.0.0.9:6379/5");
                },
                () -> 0,
                () -> new int[]{1, 1},
                buffer);

        assertThat(thrown).hasMessageContaining("cleanup incomplete");
        assertThat(thrown.getSuppressed()).as("原始清理异常须以 suppressed 保留").isNotEmpty();
        String out = buffer.toString(StandardCharsets.UTF_8);
        assertThat(out).contains("redisLeftover=0")
                .contains("cleanup-incomplete-suppressed=RedisConnectionFailureException");
        assertThat(out).doesNotContain("10.0.0.9").doesNotContain("6379").doesNotContain("secret");
    }

    @Test
    @DisplayName("SCAN 复核到残留键 >0 ⇒ 失败")
    void scanLeftoverFails() {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        IllegalStateException thrown = runExpectingFailure(
                () -> { },
                () -> 3,
                () -> new int[]{0, 0},
                buffer);
        assertThat(thrown).hasMessageContaining("cleanup incomplete");
        assertThat(buffer.toString(StandardCharsets.UTF_8)).contains("redisLeftover=3");
    }

    @Test
    @DisplayName("SCAN 自身抛异常（无法复核）⇒ 失败，输出 unverified")
    void scanThrowsFails() {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        IllegalStateException thrown = runExpectingFailure(
                () -> { },
                () -> {
                    throw new QueryTimeoutException("timeout host=10.0.0.9:6379");
                },
                () -> new int[]{0, 0},
                buffer);
        assertThat(thrown).hasMessageContaining("cleanup incomplete");
        String out = buffer.toString(StandardCharsets.UTF_8);
        assertThat(out).contains("redisLeftover=unverified")
                .contains("cleanup-incomplete-suppressed=QueryTimeoutException");
        assertThat(out).doesNotContain("10.0.0.9").doesNotContain("6379");
    }

    @Test
    @DisplayName("DB 删除抛异常 ⇒ 失败（并以 suppressed 保留），输出只含类名")
    void dbThrowsFails() {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        IllegalStateException thrown = runExpectingFailure(
                () -> { },
                () -> 0,
                () -> {
                    throw new IllegalStateException("db host=10.0.0.9 password=secret");
                },
                buffer);
        assertThat(thrown).hasMessageContaining("cleanup incomplete");
        assertThat(thrown.getSuppressed()).isNotEmpty();
        String out = buffer.toString(StandardCharsets.UTF_8);
        assertThat(out).contains("db-cleanup-error exception=IllegalStateException");
        assertThat(out).doesNotContain("10.0.0.9").doesNotContain("password").doesNotContain("secret");
    }

    @Test
    @DisplayName("全部成功 ⇒ 不抛，输出计数")
    void allOkPasses() {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        L3Cleanup.run(() -> { }, () -> 0, () -> new int[]{2, 1},
                new PrintStream(buffer, true, StandardCharsets.UTF_8));
        String out = buffer.toString(StandardCharsets.UTF_8);
        assertThat(out).contains("redisLeftover=0")
                .contains("destinationsDeleted=2")
                .contains("accountsDeleted=1")
                .doesNotContain("cleanup-incomplete-suppressed");
    }

    @Test
    @DisplayName("DB 删除行数为 0 也如实输出且不失败")
    void dbZeroRowsReportsAndPasses() {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        L3Cleanup.run(() -> { }, () -> 0, () -> new int[]{0, 0},
                new PrintStream(buffer, true, StandardCharsets.UTF_8));
        String out = buffer.toString(StandardCharsets.UTF_8);
        assertThat(out).contains("destinationsDeleted=0").contains("accountsDeleted=0");
        assertThat(out).doesNotContain("cleanup-incomplete-suppressed");
    }

    @Test
    @DisplayName("多个步骤同时失败 ⇒ suppressed 累积（至少 1 个）")
    void suppressedAccumulates() {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        IllegalStateException thrown = runExpectingFailure(
                () -> {
                    throw new RedisConnectionFailureException("connect fail");
                },
                () -> 0,
                () -> {
                    throw new IllegalStateException("db fail");
                },
                buffer);
        assertThat(thrown.getSuppressed()).isNotEmpty();
    }

    // ---------- helpers ----------

    private static IllegalStateException runExpectingFailure(
            L3Cleanup.RedisDelete delete, L3Cleanup.RedisScan scan, L3Cleanup.DbDelete db, ByteArrayOutputStream out) {
        IllegalStateException thrown = null;
        try {
            L3Cleanup.run(delete, scan, db, new PrintStream(out, true, StandardCharsets.UTF_8));
        } catch (IllegalStateException failure) {
            thrown = failure;
        }
        assertThat(thrown).as("cleanup must fail").isNotNull();
        return thrown;
    }
}

package cn.yuanxin.mvp.web.state;

import ch.qos.logback.classic.Logger;
import ch.qos.logback.classic.spi.ILoggingEvent;
import ch.qos.logback.core.read.ListAppender;
import cn.yuanxin.mvp.web.error.ApiException;
import cn.yuanxin.mvp.web.error.ErrorCode;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.slf4j.LoggerFactory;
import org.springframework.dao.QueryTimeoutException;
import org.springframework.data.redis.RedisConnectionFailureException;
import org.springframework.data.redis.RedisSystemException;

import java.util.List;
import java.util.stream.Collectors;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.catchThrowable;

/**
 * {@link RedisFailures} 日志脱敏与白名单错误码测试：绝不记录异常 {@code getMessage()}
 * （含 host:port / 口令样式 / 中文 / 换行），只允许白名单固定词或 {@code <unclassified>}。
 */
class RedisFailuresTest {

    private Logger logger;
    private ListAppender<ILoggingEvent> appender;

    @BeforeEach
    void attach() {
        logger = (Logger) LoggerFactory.getLogger(RedisFailures.class);
        appender = new ListAppender<>();
        appender.start();
        logger.addAppender(appender);
    }

    @AfterEach
    void detach() {
        logger.detachAppender(appender);
    }

    @Test
    @DisplayName("连接失败：日志不含 host/port/口令/URL，只含 operation 与异常类名")
    void connectionFailureIsRedacted() {
        String message = "Unable to connect to redis://user:secret@10.0.0.9:6379/5";
        Throwable thrown = catchThrowable(() -> RedisFailures.call("authenticate", () -> {
            throw new RedisConnectionFailureException(message);
        }));
        assertThat(thrown).isInstanceOf(ApiException.class);
        assertThat(((ApiException) thrown).getCode()).isEqualTo(ErrorCode.DEPENDENCY_UNAVAILABLE);
        assertThat(logs()).contains("operation=authenticate")
                .contains("RedisConnectionFailureException");
        assertNoSensitive(logs());
    }

    @Test
    @DisplayName("RedisSystemException 携带拓扑/口令/中文/换行 ⇒ 只记 <unclassified>")
    void systemExceptionWithTopologyIsUnclassified() {
        String message = "boom host=10.0.0.9:6379 password=secret 中文\nsecond line";
        catchThrowable(() -> RedisFailures.call("op", () -> {
            throw new RedisSystemException(message, new IllegalStateException(message));
        }));
        assertThat(logs()).contains("operation=op").contains("serverCode=<unclassified>");
        assertNoSensitive(logs());
        assertThat(logs()).doesNotContain("中文").doesNotContain("second line");
    }

    @Test
    @DisplayName("白名单：DB index out of range / WRONGPASS 只记固定词")
    void whitelistCodesAreExtracted() {
        assertThat(RedisFailures.whitelistedServerCode(new RedisSystemException(
                "ERR DB index is out of range: host=10.0.0.9:6379")))
                .isEqualTo("DB index is out of range");
        assertThat(RedisFailures.whitelistedServerCode(new RedisSystemException(
                "WRONGPASS invalid username-password pair or user is disabled. host=10.0.0.9")))
                .isEqualTo("WRONGPASS");
        assertThat(RedisFailures.whitelistedServerCode(new RedisSystemException("nothing known")))
                .isEqualTo("<unclassified>");

        catchThrowable(() -> RedisFailures.call("op", () -> {
            throw new RedisSystemException("WRONGPASS invalid username-password pair host=10.0.0.9");
        }));
        assertThat(logs()).contains("serverCode=WRONGPASS");
        assertThat(logs()).doesNotContain("invalid username-password").doesNotContain("10.0.0.9");
    }

    @Test
    @DisplayName("命令超时：日志只含类名与 operation")
    void queryTimeoutIsRedacted() {
        catchThrowable(() -> RedisFailures.call("verify-challenge", () -> {
            throw new QueryTimeoutException("timeout connecting 10.0.0.9:6379");
        }));
        assertThat(logs()).contains("operation=verify-challenge").contains("QueryTimeoutException");
        assertNoSensitive(logs());
    }

    @Test
    @DisplayName("非后端故障（代码缺陷）原样抛出且不写日志")
    void nonStoreFailureIsNotTranslatedOrLogged() {
        IllegalStateException defect = new IllegalStateException("bug host=10.0.0.9");
        RuntimeException returned = RedisFailures.failClosed("op", defect);
        assertThat(returned).isSameAs(defect);
        assertThat(appender.list).isEmpty();
    }

    private String logs() {
        return appender.list.stream().map(ILoggingEvent::getFormattedMessage)
                .collect(Collectors.joining("\n"));
    }

    private static void assertNoSensitive(String text) {
        List<String> forbidden = List.of("10.0.0.9", "6379", "secret", "redis://", "password");
        for (String token : forbidden) {
            assertThat(text).as("log must not contain '%s'", token).doesNotContain(token);
        }
    }
}

